INSERT INTO destrezas_curriculares (materia_id, curriculo_id, grado, codigo, descripcion, grupo, activo, created_at, updated_at) VALUES
(@materia_matematica_id, @curriculo_anterior_id, 2, 'M.2.1.10', 'Identificar los elementos de salida y de llegada en pares ordenados sencillos representados en una cuadrícula, con apoyo gráfico. (Ref. M.2.1.10.)', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 2, 'M.2.1.8', 'Identificar relaciones entre elementos de un conjunto de salida y un conjunto de llegada, mediante material concreto o flechas, y representarlas como pares ordenados sencillos. (Ref. M.2.1.8.)', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 2, 'M.2.1.23', 'Aplicar la propiedad conmutativa de la adición en cálculos mentales sencillos con números de hasta dos cifras, utilizando material concreto o representaciones gráficas. (Ref. M.2.1.23.)', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 2, 'M.2.1.31', 'Relacionar repartos exactos y agrupaciones iguales con multiplicaciones sencillas, reconociendo la multiplicación y la división como operaciones inversas con apoyo concreto. (Ref. M.2.1.31.)', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 2, 'M.2.1.32', 'Calcular mentalmente dobles y mitades de cantidades pequeñas mediante agrupaciones, repartos y otras estrategias sencillas. (Ref. M.2.1.32.)', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 2, 'M.2.2.8', 'Representar gráficamente segmentos y semirrectas sencillas, e identificar ángulos formados por dos semirrectas con un mismo origen. (Ref. M.2.2.8.)', 2, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 2, 'M.2.2.12', 'Relacionar el metro con el centímetro mediante mediciones y equivalencias concretas sencillas. (Ref. M.2.2.12.)', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 2, 'M.2.2.21', 'Relacionar el kilogramo y el gramo mediante comparaciones y equivalencias concretas sencillas. (Ref. M.2.2.21.)', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 2, 'M.2.2.22', 'Reconocer la libra como unidad de medida de masa presente en productos y situaciones cotidianas. (Ref. M.2.2.22.)', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 2, 'M.2.2.25', 'Relacionar el litro con recipientes de menor capacidad mediante comparaciones y equivalencias concretas sencillas. (Ref. M.2.2.25.)', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 2, 'M.2.3.3', 'Reconocer situaciones cotidianas o juegos sencillos cuyos resultados pueden variar, e identificar resultados posibles. (Ref. M.2.3.3.)', 4, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 3, 'M.2.1.10', 'Identificar los elementos de los conjuntos de salida y de llegada a partir de pares ordenados ubicados en una cuadrícula. (Ref. M.2.1.10.)', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 3, 'M.2.1.8', 'Identificar los elementos relacionados de conjuntos de salida y de llegada, representar la relación mediante diagramas y formar pares ordenados del producto cartesiano. (Ref. M.2.1.8.)', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 3, 'M.2.1.23', 'Aplicar las propiedades conmutativa y asociativa de la adición en estrategias de cálculo mental con números de hasta tres cifras. (Ref. M.2.1.23.)', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 3, 'M.2.1.31', 'Reconocer y comprobar la relación inversa entre la multiplicación y la división exacta mediante ejemplos, arreglos y tablas de multiplicar. (Ref. M.2.1.31.)', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 3, 'M.2.1.32', 'Calcular mentalmente productos de las tablas estudiadas y cocientes exactos relacionados, utilizando descomposición, dobles y otras estrategias. (Ref. M.2.1.32.)', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 3, 'M.2.2.8', 'Representar gráficamente semirrectas, segmentos y ángulos en cuadrículas o con instrumentos de dibujo, identificando sus elementos básicos. (Ref. M.2.2.8.)', 2, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 3, 'M.2.2.12', 'Realizar conversiones simples del metro a decímetros y centímetros en situaciones de medición del entorno. (Ref. M.2.2.12.)', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 3, 'M.2.2.21', 'Realizar conversiones simples entre kilogramos y gramos en situaciones de medición de masa. (Ref. M.2.2.21.)', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 3, 'M.2.2.22', 'Identificar la libra como unidad de medida de masa de uso cotidiano y compararla con otras unidades conocidas. (Ref. M.2.2.22.)', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 3, 'M.2.2.25', 'Realizar conversiones simples del litro a sus submúltiplos en situaciones de medición de capacidad. (Ref. M.2.2.25.)', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 3, 'M.2.3.3', 'Reconocer experiencias aleatorias en juegos y situaciones cotidianas, y describir sus posibles resultados. (Ref. M.2.3.3.)', 4, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 4, 'M.2.1.10', 'M.2.1.10. Identificar los elementos de los conjuntos de salida y de llegada, a partir de los pares ordenados representados en una cuadrícula.', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 4, 'M.2.1.8', 'M.2.1.8. Identificar los elementos relacionados de un conjunto de salida y un conjunto de llegada como pares ordenados del producto cartesiano AxB.', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 4, 'M.2.1.23', 'M.2.1.23. Aplicar las propiedades conmutativa y asociativa de la adición en estrategias de cálculo mental.', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 4, 'M.2.1.31', 'M.2.1.31. Reconocer la relación entre división y multiplicación como operaciones inversas.', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 4, 'M.2.1.32', 'M.2.1.32. Calcular mentalmente productos y cocientes exactos utilizando varias estrategias.', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 4, 'M.2.2.8', 'M.2.2.8. Representar de forma gráfica la semirrecta, el segmento y el ángulo.', 2, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 4, 'M.2.2.12', 'M.2.2.12. Realizar conversiones simples de medidas de longitud del metro a sus submúltiplos.', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 4, 'M.2.2.21', 'M.2.2.21. Realizar conversiones simples de medidas de masa.', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 4, 'M.2.2.22', 'M.2.2.22. Identificar la libra como unidad de medida de masa.', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 4, 'M.2.2.25', 'M.2.2.25. Realizar conversiones simples de medidas de capacidad del litro a sus submúltiplos.', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 4, 'M.2.3.3', 'M.2.3.3. Reconocer experiencias aleatorias en situaciones cotidianas.', 4, 1, NOW(), NOW())
INSERT INTO indicadores_evaluacion (materia_id, curriculo_id, grado, codigo, descripcion, grupo, activo, created_at, updated_at) VALUES
(@materia_matematica_id, @curriculo_anterior_id, 2, 'I.M.2.2.1', 'Completa secuencias numéricas ascendentes o descendentes con números naturales de hasta dos cifras, utilizando material concreto, estrategias de conteo y la semirrecta numérica; separa números pares e impares mediante agrupaciones. (Ref. I.M.2.2.1.) (I.3.)', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 2, 'I.M.2.2.3', 'Resuelve problemas sencillos del entorno con adiciones y sustracciones de números de hasta dos cifras; aplica la propiedad conmutativa y, con apoyo concreto, la asociativa para mostrar y verificar resultados. (Ref. I.M.2.2.3.) (I.2., I.4.)', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 2, 'I.M.2.2.4', 'Representa multiplicaciones como grupos iguales y repartos exactos con cantidades pequeñas; usa la propiedad conmutativa en productos sencillos y reconoce mitades y dobles. (Ref. I.M.2.2.4.) (I.2., I.4.)', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 2, 'I.M.2.4.1', 'Resuelve situaciones sencillas que requieren comparar longitudes y establecer equivalencias concretas entre el metro y el centímetro. (Ref. I.M.2.4.1.) (I.2.)', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 2, 'I.M.2.4.3', 'Utiliza unidades de tiempo y lee en el reloj analógico horas en punto y medias horas para describir sus actividades cotidianas. (Ref. I.M.2.4.3.) (J.2., I.3.)', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 2, 'I.M.2.4.4', 'Resuelve situaciones sencillas que requieren comparar masas, establecer equivalencias concretas entre kilogramo y gramo e identificar la libra como unidad de uso cotidiano. (Ref. I.M.2.4.4.) (I.2., I.4.)', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 2, 'I.M.2.4.5', 'Resuelve situaciones sencillas que requieren comparar capacidades y establecer equivalencias concretas entre el litro y recipientes de menor capacidad. (Ref. I.M.2.4.5.) (I.2., I.4.)', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 2, 'I.M.2.5.3', 'Identifica resultados posibles en experiencias aleatorias sencillas realizadas mediante juegos y comenta lo observado. (Ref. I.M.2.5.3.) (I.1.)', 4, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 3, 'I.M.2.2.1', 'Completa secuencias numéricas ascendentes o descendentes con números naturales de hasta tres cifras, utilizando material concreto, simbologías, estrategias de conteo y la semirrecta numérica; clasifica números pares e impares. (Ref. I.M.2.2.1.) (I.3.)', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 3, 'I.M.2.2.3', 'Resuelve problemas del entorno con adiciones y sustracciones de números de hasta tres cifras; emplea las propiedades conmutativa y asociativa de la adición para mostrar procesos y verificar resultados. (Ref. I.M.2.2.3.) (I.2., I.4.)', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 3, 'I.M.2.2.4', 'Resuelve problemas sencillos mediante multiplicaciones sin reagrupación y divisiones exactas; usa las propiedades conmutativa y asociativa de la multiplicación para mostrar y verificar procesos, y reconoce mitades y dobles. (Ref. I.M.2.2.4.) (I.2., I.4.)', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 3, 'I.M.2.4.1', 'Resuelve situaciones sencillas que requieren comparar longitudes y realizar conversiones simples entre metro, decímetro y centímetro. (Ref. I.M.2.4.1.) (I.2.)', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 3, 'I.M.2.4.3', 'Utiliza días, semanas, meses, horas y minutos, y lee el reloj analógico para describir y organizar sus actividades cotidianas. (Ref. I.M.2.4.3.) (J.2., I.3.)', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 3, 'I.M.2.4.4', 'Resuelve situaciones sencillas que requieren comparar masas, realizar conversiones simples entre kilogramo y gramo e identificar la libra como unidad de medida de masa. (Ref. I.M.2.4.4.) (I.2., I.4.)', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 3, 'I.M.2.4.5', 'Resuelve situaciones sencillas que requieren estimar y comparar capacidades, y realizar conversiones simples entre el litro y sus submúltiplos. (Ref. I.M.2.4.5.) (I.2., I.4.)', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 3, 'I.M.2.5.3', 'Analiza experiencias aleatorias en juegos, reconoce posibles resultados y compara lo ocurrido en varias repeticiones. (Ref. I.M.2.5.3.) (I.1.)', 4, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 4, 'I.M.2.2.1', 'I.M.2.2.1. Completa secuencias numéricas ascendentes o descendentes con números naturales de hasta cuatro cifras, utilizando material concreto, simbologías, estrategias de conteo y la representación en la semirrecta numérica; separa números pares e impares. (I.3.)', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 4, 'I.M.2.2.3', 'I.M.2.2.3. Opera utilizando la adición y sustracción con números naturales de hasta cuatro cifras en el contexto de un problema matemático del entorno, y emplea las propiedades conmutativa y asociativa de la adición para mostrar procesos y verificar resultados. (I.2., I.4.)', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 4, 'I.M.2.2.4', 'I.M.2.2.4. Opera utilizando la multiplicación sin reagrupación y la división exacta (divisor de una cifra) con números naturales en el contexto de un problema del entorno; usa reglas y las propiedades conmutativa y asociativa de la multiplicación para mostrar procesos y verificar resultados; reconoce mitades y dobles en objetos. (I.2., I.4.)', 1, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 4, 'I.M.2.4.1', 'I.M.2.4.1. Resuelve situaciones problémicas sencillas que requieran de la comparación de longitudes y la conversión de unidades. (I.2.)', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 4, 'I.M.2.4.3', 'I.M.2.4.3. Utiliza las unidades de tiempo y la lectura del reloj analógico para describir sus actividades cotidianas. (J.2., I.3.)', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 4, 'I.M.2.4.4', 'I.M.2.4.4. Resuelve situaciones problémicas sencillas que requieran de la comparación de la masa de objetos del entorno, de la conversión entre kilogramo y gramo, y la identificación de la libra como unidad de medida de masa. (I.2., I.4.)', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 4, 'I.M.2.4.5', 'I.M.2.4.5. Resuelve situaciones problémicas sencillas que requieran de la estimación y comparación de capacidades y la conversión entre la unidad de medida de capacidad y sus submúltiplos. (I.2., I.4.)', 3, 1, NOW(), NOW()),
(@materia_matematica_id, @curriculo_anterior_id, 4, 'I.M.2.5.3', 'I.M.2.5.3. Analiza una experiencia aleatoria en actividades lúdicas. (I.1.)', 4, 1, NOW(), NOW())
INSERT INTO destreza_indicador (destreza_curricular_id, indicador_evaluacion_id) SELECT destreza.id, indicador.id FROM destrezas_curriculares destreza INNER JOIN indicadores_evaluacion indicador ON indicador.materia_id = destreza.materia_id AND indicador.curriculo_id = destreza.curriculo_id AND indicador.grado = destreza.grado AND indicador.grupo = destreza.grupo WHERE destreza.materia_id = @materia_matematica_id AND destreza.curriculo_id = @curriculo_anterior_id AND destreza.grupo IN (1, 3, 4);
INSERT INTO destreza_indicador (destreza_curricular_id, indicador_evaluacion_id) SELECT destreza.id, indicador.id FROM destrezas_curriculares destreza INNER JOIN indicadores_evaluacion indicador ON indicador.materia_id = destreza.materia_id AND indicador.curriculo_id = @curriculo_actual_id AND indicador.grado = destreza.grado AND indicador.grupo = destreza.grupo AND indicador.activo = 1 WHERE destreza.materia_id = @materia_matematica_id AND destreza.curriculo_id = @curriculo_anterior_id AND destreza.grupo IN (1, 2, 3, 4);
