START TRANSACTION;

SET @materia_matematica_id := (SELECT id FROM materias WHERE nombre = 'Matemática' LIMIT 1);
SET @curriculo_actual_id := (SELECT id FROM curriculos WHERE codigo = 'priorizado-2025' LIMIT 1);
SET @curriculo_anterior_id := (SELECT id FROM curriculos WHERE codigo = 'obligatorio-elemental' LIMIT 1);

UPDATE destrezas_curriculares SET curriculo_id = @curriculo_actual_id WHERE materia_id = @materia_matematica_id AND curriculo_id IS NULL;
UPDATE indicadores_evaluacion SET curriculo_id = @curriculo_actual_id WHERE materia_id = @materia_matematica_id AND curriculo_id IS NULL;
UPDATE indicadores_evaluacion SET codigo = CONCAT('Ref.', codigo) WHERE materia_id = @materia_matematica_id AND curriculo_id = @curriculo_actual_id AND codigo IN ('I.M.2.2.1', 'I.M.2.2.3', 'I.M.2.2.4', 'I.M.2.4.1', 'I.M.2.4.3', 'I.M.2.4.4', 'I.M.2.4.5');

UPDATE destrezas_curriculares SET activo = 0 WHERE materia_id = @materia_matematica_id AND curriculo_id = @curriculo_anterior_id;
UPDATE indicadores_evaluacion SET activo = 0 WHERE materia_id = @materia_matematica_id AND curriculo_id = @curriculo_anterior_id;

ON DUPLICATE KEY UPDATE descripcion = VALUES(descripcion), grupo = VALUES(grupo), activo = 1, updated_at = NOW();

ON DUPLICATE KEY UPDATE descripcion = VALUES(descripcion), grupo = VALUES(grupo), activo = 1, updated_at = NOW();

DELETE relacion FROM destreza_indicador relacion INNER JOIN destrezas_curriculares destreza ON destreza.id = relacion.destreza_curricular_id WHERE destreza.materia_id = @materia_matematica_id AND destreza.curriculo_id = @curriculo_anterior_id;

COMMIT;

SELECT 'Currículo 2025' AS origen, COUNT(*) AS indicadores FROM indicadores_evaluacion WHERE materia_id = @materia_matematica_id AND curriculo_id = @curriculo_actual_id;
SELECT 'Currículo anterior' AS origen, COUNT(*) AS indicadores FROM indicadores_evaluacion WHERE materia_id = @materia_matematica_id AND curriculo_id = @curriculo_anterior_id;
